package org.fireflyframework.koinon.sdk.api;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import org.fireflyframework.koinon.sdk.*;
import org.fireflyframework.koinon.sdk.internal.Transport;
import org.fireflyframework.koinon.sdk.model.*;

public final class ChatAttachmentsApi {
private final Transport transport; private final String prefix;
public ChatAttachmentsApi(Transport transport,String tenantId){this.transport=Objects.requireNonNull(transport);this.prefix="/tenants/"+Transport.id(tenantId);}
public AttachmentCapabilities capabilities(String threadId,RequestOptions options){Objects.requireNonNull(options);return transport.json("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/capabilities",null,options,transport.type(AttachmentCapabilities.class));}
public AttachmentCapabilities capabilities(String threadId){return capabilities(threadId,RequestOptions.defaults());}
public CompletableFuture<AttachmentCapabilities> capabilitiesAsync(String threadId,RequestOptions options){Objects.requireNonNull(options);return transport.jsonAsync("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/capabilities",null,options,transport.type(AttachmentCapabilities.class));}
public CompletableFuture<AttachmentCapabilities> capabilitiesAsync(String threadId){return capabilitiesAsync(threadId,RequestOptions.defaults());}
public AttachmentView upload(String threadId,AttachmentUpload input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.multipart("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments",input.file(),"file",input.mediaType(),Map.of(),options,transport.type(AttachmentView.class));}
public AttachmentView upload(String threadId,AttachmentUpload input,String idempotencyKey){return upload(threadId,input,idempotencyKey,RequestOptions.defaults());}
public CompletableFuture<AttachmentView> uploadAsync(String threadId,AttachmentUpload input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.multipartAsync("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments",input.file(),"file",input.mediaType(),Map.of(),options,transport.type(AttachmentView.class));}
public CompletableFuture<AttachmentView> uploadAsync(String threadId,AttachmentUpload input,String idempotencyKey){return uploadAsync(threadId,input,idempotencyKey,RequestOptions.defaults());}
public AttachmentPage list(String threadId,AttachmentFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments",null,options,transport.type(AttachmentPage.class));}
public AttachmentPage list(String threadId,AttachmentFilter filter){return list(threadId,filter,RequestOptions.defaults());}
public AttachmentPage list(String threadId){return list(threadId,AttachmentFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<AttachmentPage> listAsync(String threadId,AttachmentFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments",null,options,transport.type(AttachmentPage.class));}
public CompletableFuture<AttachmentPage> listAsync(String threadId,AttachmentFilter filter){return listAsync(threadId,filter,RequestOptions.defaults());}
public CompletableFuture<AttachmentPage> listAsync(String threadId){return listAsync(threadId,AttachmentFilter.empty(),RequestOptions.defaults());}
public AttachmentView get(String threadId,String attachmentId,RequestOptions options){Objects.requireNonNull(options);return transport.json("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId),null,options,transport.type(AttachmentView.class));}
public AttachmentView get(String threadId,String attachmentId){return get(threadId,attachmentId,RequestOptions.defaults());}
public CompletableFuture<AttachmentView> getAsync(String threadId,String attachmentId,RequestOptions options){Objects.requireNonNull(options);return transport.jsonAsync("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId),null,options,transport.type(AttachmentView.class));}
public CompletableFuture<AttachmentView> getAsync(String threadId,String attachmentId){return getAsync(threadId,attachmentId,RequestOptions.defaults());}
public BinaryResponse original(String threadId,String attachmentId,RequestOptions options){Objects.requireNonNull(options);return transport.binary("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/original",options);}
public BinaryResponse original(String threadId,String attachmentId){return original(threadId,attachmentId,RequestOptions.defaults());}
public CompletableFuture<BinaryResponse> originalAsync(String threadId,String attachmentId,RequestOptions options){Objects.requireNonNull(options);return transport.binaryAsync("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/original",options);}
public CompletableFuture<BinaryResponse> originalAsync(String threadId,String attachmentId){return originalAsync(threadId,attachmentId,RequestOptions.defaults());}
public FileDownload downloadOriginal(String threadId,String attachmentId,Path target,long maxBytes,RequestOptions options){Objects.requireNonNull(options);return transport.download("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/original",target,maxBytes,options);}
public CompletableFuture<FileDownload> downloadOriginalAsync(String threadId,String attachmentId,Path target,long maxBytes,RequestOptions options){Objects.requireNonNull(options);return transport.downloadAsync("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/original",target,maxBytes,options);}
public PrivateChunkPage chunks(String threadId,String attachmentId,AttachmentChunkFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/chunks",null,options,transport.type(PrivateChunkPage.class));}
public PrivateChunkPage chunks(String threadId,String attachmentId,AttachmentChunkFilter filter){return chunks(threadId,attachmentId,filter,RequestOptions.defaults());}
public PrivateChunkPage chunks(String threadId,String attachmentId){return chunks(threadId,attachmentId,AttachmentChunkFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<PrivateChunkPage> chunksAsync(String threadId,String attachmentId,AttachmentChunkFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/chunks",null,options,transport.type(PrivateChunkPage.class));}
public CompletableFuture<PrivateChunkPage> chunksAsync(String threadId,String attachmentId,AttachmentChunkFilter filter){return chunksAsync(threadId,attachmentId,filter,RequestOptions.defaults());}
public CompletableFuture<PrivateChunkPage> chunksAsync(String threadId,String attachmentId){return chunksAsync(threadId,attachmentId,AttachmentChunkFilter.empty(),RequestOptions.defaults());}
public AttachmentView cancel(String threadId,String attachmentId,AttachmentRevision input,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);return transport.json("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/cancel",input,options,transport.type(AttachmentView.class));}
public AttachmentView cancel(String threadId,String attachmentId,AttachmentRevision input){return cancel(threadId,attachmentId,input,RequestOptions.defaults());}
public CompletableFuture<AttachmentView> cancelAsync(String threadId,String attachmentId,AttachmentRevision input,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/cancel",input,options,transport.type(AttachmentView.class));}
public CompletableFuture<AttachmentView> cancelAsync(String threadId,String attachmentId,AttachmentRevision input){return cancelAsync(threadId,attachmentId,input,RequestOptions.defaults());}
public AttachmentView retry(String threadId,String attachmentId,AttachmentRevision input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.json("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/retry",input,options,transport.type(AttachmentView.class));}
public AttachmentView retry(String threadId,String attachmentId,AttachmentRevision input,String idempotencyKey){return retry(threadId,attachmentId,input,idempotencyKey,RequestOptions.defaults());}
public CompletableFuture<AttachmentView> retryAsync(String threadId,String attachmentId,AttachmentRevision input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/retry",input,options,transport.type(AttachmentView.class));}
public CompletableFuture<AttachmentView> retryAsync(String threadId,String attachmentId,AttachmentRevision input,String idempotencyKey){return retryAsync(threadId,attachmentId,input,idempotencyKey,RequestOptions.defaults());}
public Void remove(String threadId,String attachmentId,AttachmentDeleteFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("DELETE",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId),null,options,transport.type(Void.class));}
public Void remove(String threadId,String attachmentId,AttachmentDeleteFilter filter){return remove(threadId,attachmentId,filter,RequestOptions.defaults());}
public CompletableFuture<Void> removeAsync(String threadId,String attachmentId,AttachmentDeleteFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("DELETE",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId),null,options,transport.type(Void.class));}
public CompletableFuture<Void> removeAsync(String threadId,String attachmentId,AttachmentDeleteFilter filter){return removeAsync(threadId,attachmentId,filter,RequestOptions.defaults());}
public AttachmentPromotionView promote(String threadId,String attachmentId,AttachmentPromotionInput input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.json("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/knowledge",input,options,transport.type(AttachmentPromotionView.class));}
public AttachmentPromotionView promote(String threadId,String attachmentId,AttachmentPromotionInput input,String idempotencyKey){return promote(threadId,attachmentId,input,idempotencyKey,RequestOptions.defaults());}
public CompletableFuture<AttachmentPromotionView> promoteAsync(String threadId,String attachmentId,AttachmentPromotionInput input,String idempotencyKey,RequestOptions options){Objects.requireNonNull(options);options=options.idempotencyKey(Objects.requireNonNull(idempotencyKey));Objects.requireNonNull(input);return transport.jsonAsync("POST",prefix+"/chat/threads/"+Transport.id(threadId)+"/attachments/"+Transport.id(attachmentId)+"/knowledge",input,options,transport.type(AttachmentPromotionView.class));}
public CompletableFuture<AttachmentPromotionView> promoteAsync(String threadId,String attachmentId,AttachmentPromotionInput input,String idempotencyKey){return promoteAsync(threadId,attachmentId,input,idempotencyKey,RequestOptions.defaults());}
}
